pub fn quot_lift_h() -> Expr {
    pi(
        bv(3),
        pi(
            bv(4),
            pi(
                ap2(bv(4), bv(1), bv(0)),
                ap3(
                    cnst(bnm::eq_name(), vec1(v())),
                    bv(4),
                    expr::app(bv(3), bv(2)),
                    expr::app(bv(3), bv(1)),
                ),
            ),
        ),
    )
}

/// con-leche: ConLeche/Kernel/Basis/Quot.lean:55-72 quotLiftRaw
/// `Quot.lift.{u, v} {α : Sort u} {r : α → α → Prop} {β : Sort v}
