pub fn quot_lift_raw() -> ConstantInfo {
    ConstantInfo::RecInfo(
        cv(
            bnm::quot_lift_name(),
            vec2(u_n(), v_n()),
            pi(
                srt(u()),
                pi(
                    quot_rel(),
                    pi(
                        srt(v()),
                        pi(
                            quot_lift_f(),
                            pi(
                                quot_lift_h(),
                                pi(
                                    ap2(cnst(bnm::quot_name(), vec1(u())), bv(4), bv(3)),
                                    bv(3),
                                ),
                            ),
                        ),
                    ),
                ),
            ),
        ),
        5,
        5,
        vec1(rule(
            bnm::quot_mk_name(),
            1,
            lm(
                srt(u()),
                lm(
                    quot_rel(),
                    lm(
                        srt(v()),
                        lm(
                            quot_lift_f(),
                            lm(
                                quot_lift_h(),
                                lm(bv(4), expr::app(bv(2), bv(0))),
                            ),
                        ),
                    ),
                ),
            ),
        )),
    )
}

